import{promises as fs}from'node:fs';for(const p of['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}`)});const add=async(f,p,m)=>{let s=await fs.readFile(f,'utf8');if(!s.includes(m)){s+='\n'+await fs.readFile(p,'utf8');await fs.writeFile(f,s)}};await add('scripts/build.mjs','v23-4-build-patch.txt','V23.4 ORPHAN AUDIO CONTROL KILL SWITCH');await add('assets/atlas.css','v23-4-css-patch.txt','V23.4 hide every orphan audio fragment');await fs.copyFile('audio-orphan-killer.js','assets/audio-orphan-killer.js');console.log('V23.4 kuruldu: kopuk Automatic/voice alanları ve siyah şeritler global olarak etkisizleştirildi.');
